mapper.update:
update points_exchange
status = #{status}, receive_info = #{receiveInfo},
where id = #{id}

mapper.select:
select e.*, u.username, u.name as userName, g.name as goodsName from points_exchange e left join `user` u on e.user_id = u.id left join points_goods g on e.goods_id = g.id
and e.status = #{status}
order by e.create_time desc
